class Solution {
public:
    int maxDivisibilityScore(std::vector<int>& nums, std::vector<int>& divisors) {
        int best_d = divisors[0];
        int max_score = -1;
        for (int d : divisors) {
            int score = 0;
            for (int x : nums) {
                if (x % d == 0) score++;
            }
            if (score > max_score || (score == max_score && d < best_d)) {
                max_score = score;
                best_d = d;
            }
        }
        return best_d;
    }
};

class Solution {
    public int maxDivisibilityScore(int[] nums, int[] divisors) {
        int bestD = divisors[0];
        int maxScore = -1;
        for (int d : divisors) {
            int score = 0;
            for (int x : nums) {
                if (x % d == 0) score++;
            }
            if (score > maxScore || (score == maxScore && d < bestD)) {
                maxScore = score;
                bestD = d;
            }
        }
        return bestD;
    }
}

var maxDivisibilityScore = function(nums, divisors) {
    let bestD = divisors[0];
    let maxScore = -1;
    for (const d of divisors) {
        let score = 0;
        for (const x of nums) {
            if (x % d === 0) score++;
        }
        if (score > maxScore || (score === maxScore && d < bestD)) {
            maxScore = score;
            bestD = d;
        }
    }
    return bestD;
